-- Gear three imported books print and their imports left out, each for a reason
-- that a later book's import showed was not a limit.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
-- Rifts World Book 23: Xiticix Invasion, printed 105: the Deathbringer
--   exoskeleton armor. Left out "because no price or weight is printed"; a NULL
--   cost has been a finished row since 2026-09-07 (db/schema.sql, gear.cost),
--   and China 2's Demon Skin is the same shape. Its M.D.C. is rolled (3D6+50),
--   so mdc is NULL and the dice are in the description.
-- Rifts World Book 19: Australia, printed 98-99: the automated sentry gun and
--   the two sizes of Tech-City defense turret. Left out as "fixed
--   emplacements"; Canada stored one the next day (tr-500-heavy-laser-turret).
--   The book prints ONE M.D.C. block for both turret sizes without saying
--   which figure is which, so neither turret stores an mdc; the printed pairs
--   are in the description. The laser net does no damage and is not a row.
-- Rifts World Book 17: Warlords of Russia, printed 187-189: 132 items from the
--   three price lists (camping and field gear, containers, miscellaneous
--   equipment, clothing). Left by the session, not by a decision; Australia's
--   Decision 3 (2026-10-01) imports a price list as gear rows with the range
--   in cost_note. cost is the low end of a printed range.
--
-- EVERY NUMBER WAS READ OFF A RENDER and checked against a render again by
-- book-reconcile: 136 rows, no wrong figure. The reverse check found no
-- priced line on printed 187-189 without a row, other than the items below.
--
-- NOT HERE, on purpose:
--   25 list items the catalog already holds for Rifts (canteens, knives, rope,
--     the gas mask and the like). Seven of those held rows are web-reference or
--     estimate rows whose price disagrees with this book (large and small
--     sack, saddlebags, hooded robe, poncho, fishing net, throwing knife);
--     they are named in the Warlords survey and left for a separate correction.
--   Three lines on printed 189 that the INK garbles (two entries typeset
--     through one another); no row is guessed from them.
--   72 slugs carry `-rifts`: the bare slug belongs to a Heroes Unlimited or
--     Palladium Fantasy row of the same name, a different item at a dollar or
--     gold price. Japan's chain-per-foot-rifts is the precedent.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
('deathbringer-xiticix-exoskeleton-armor', 'Deathbringer Xiticix Exoskeleton Armor', 'rifts', 'armor', NULL, NULL, 'No price printed (printed 105).', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Body armor the Deathbringer cult''s Wild Psi-Stalkers cut from the exoskeletons of Xiticix Warriors or Leapers, reinforced and padded, and worn with a Xiticix skull helmet. Non-environmental. M.D.C.: typically 3D6+50, varying from suit to suit.', 'Rifts World Book 23: Xiticix Invasion p.105', NULL),
('tech-city-automated-sentry-gun', 'Automated Sentry Gun (ASG)', 'rifts', 'weapon', NULL, NULL, 'No price printed; a fixed emplacement in the walls of Perth and Melbourne.', '2D6 M.D. per single blast', 1, '500 feet (152 m), the default range', 'Effectively unlimited while the city holds 50% power; the ASG system shuts down if city-wide power falls below 45%', '3 attacks per melee round; an intruder is likely to be targeted by 1D4 guns at once or in quick succession', NULL, NULL, 10, 'A small, partly hidden perimeter gun set inside the base of the Tech-City walls every 100 feet (30.5 m), folding out when the laser net is cut and the Central Computer puts the guns on alert. +2 to strike. Each gun has 10 M.D.C. and needs a Called Shot (no penalty) to hit. Blind only in a strip about 5 feet (1.5 m) wide along the foot of the wall.', 'Rifts World Book 19: Australia p.98', NULL),
('tech-city-defense-turret-standard', 'Tech-City Defense Turret (Standard)', 'rifts', 'weapon', NULL, NULL, 'No price printed; a fixed emplacement of Perth and Melbourne.', '4D6 M.D. per single blast or 6D6+10 M.D. per simultaneous double blast', 1, '6000 feet (1828 m)', 'Effectively unlimited while the city holds 50% power; below 50% half the turrets lose power, below 30% only one in five keeps it. Each turret has its own emergency reserve good for 100 blasts', '3 attacks per melee round in automated mode, otherwise the hand to hand attacks of its gunner (typically 5-7); a simultaneous double blast counts as one attack', NULL, NULL, NULL, 'The double-barrelled laser turret built by the hundreds into the perimeter wall and onto buildings, the monorail and plant bunkers of both Tech-Cities, for civil defense, anti-armor and anti-aircraft work. Crew of three (gunner, back-up gunner, communications engineer) with room for three more; gunners add W.P. Heavy Weapon bonuses, +1 to strike when automated. M.D.C. by location, printed once for both sizes: laser barrels (2) 100 or 200 each, main body turret housing 300 or 400, main body bunker housing (when applicable) 1000, hatch 150, sensor cluster 35 or 50. The book does not say which figure of each pair belongs to which size, so no M.D.C. is stored.', 'Rifts World Book 19: Australia p.98-99', NULL),
('tech-city-defense-turret-heavy', 'Tech-City Defense Turret (Heavy)', 'rifts', 'weapon', NULL, NULL, 'No price printed; a fixed emplacement of Perth and Melbourne.', '1D4x10 M.D. per single blast or 2D4x10 M.D. per simultaneous double blast', 1, '10,000 feet (3048 m)', 'Effectively unlimited while the city holds 50% power; below 50% half the turrets lose power, below 30% only one in five keeps it. Each turret has its own emergency reserve good for 100 blasts', '3 attacks per melee round in automated mode, otherwise the hand to hand attacks of its gunner (typically 5-7); a simultaneous double blast counts as one attack', NULL, NULL, NULL, 'The larger turret that makes up one in every ten of the Tech-Cities'' defense turrets, with a more powerful pair of laser cannons. Crew of three (gunner, back-up gunner, communications engineer) with room for three more; gunners add W.P. Heavy Weapon bonuses, +1 to strike when automated. M.D.C. by location, printed once for both sizes: laser barrels (2) 100 or 200 each, main body turret housing 300 or 400, main body bunker housing (when applicable) 1000, hatch 150, sensor cluster 35 or 50. The book does not say which figure of each pair belongs to which size, so no M.D.C. is stored.', 'Rifts World Book 19: Australia p.98-99', NULL),
('backpack-small', 'Backpack, small, high quality', 'rifts', 'gear', NULL, 40, '40-100 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Rifts World Book 17: Warlords of Russia p.187', NULL),
('animal-trap-small', 'Animal Trap, small', 'rifts', 'gear', NULL, 30, '30-50 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Rifts World Book 17: Warlords of Russia p.187', NULL),
